messageHandlers.script:
p = BlueRidge.Common.Util.extractQualifiedValues(payload) or {}
action = p.get("action")
if action == "discard":
	system.perspective.sendMessage("reconcileBackToShifts", scope="page")
elif action == "save":
	# "Save" here means review it: the sheet's own Save is never skipped,
	# even from the Discard flow -- it still runs a preview and shows the
	# confirmation panel before anything is written.
	self.reviewAndSave()

transforms.code:
st = BlueRidge.Common.Util.extractQualifiedValues(value) or {}
rejs = st.get("rejectLines") or []
total = sum([(r.get("quantity") or 0) for r in rejs])
return "{:,}".format(total)

st = BlueRidge.Common.Util.extractQualifiedValues(value) or {}
act = st.get("actual") or {}
good = act.get("goodShots")
if good is None:
	return "N/A"
cav = self.view.custom.header.ActiveCavities or 0
rejs = st.get("rejectLines") or []
noGood = sum([(r.get("quantity") or 0) for r in rejs])
total = good * cav - noGood
return "{:,}".format(total)

st = BlueRidge.Common.Util.extractQualifiedValues(value) or {}
act = st.get("actual") or {}
good = act.get("goodShots")
if good is None:
	return "N/A"
cav = self.view.custom.header.ActiveCavities or 0
rejs = st.get("rejectLines") or []
noGood = sum([(r.get("quantity") or 0) for r in rejs])
total = good * cav - noGood
rec = self.view.custom.header.RecordedGood or 0
diff = total - rec
sign = "+" if diff > 0 else ""
return "%s%s" % (sign, "{:,}".format(diff))

rows = BlueRidge.Common.Util.extractQualifiedValues(value) or []
if not rows:
	return "No rejects on record for this shift."
totals = {}
order = []
for r in rows:
	code = r.get("DefectCode") or "?"
	if code not in totals:
		totals[code] = 0
		order.append(code)
	totals[code] += r.get("Quantity") or 0
# Summed per defect code ACROSS every part/approver row that carries it --
# the grain is (DefectCode, Part, Approver); a per-code total read off any
# one row would silently drop the others (the earlier, fixed bug).
lines = ["Recorded by code:"]
for code in order:
	lines.append("  " + code + ": " + "{:,}".format(totals[code]) + " pcs")
return "\n".join(lines)
